//! Static emoji lookup tables embedded in `.rodata`:
//!
//! 1. **Gemoji shortcode alias table (`EMOJI_BLOB` + `EMOJI_ENTRIES`)**:
//!    Generated from `gemoji` 4.1.0 (`db/emoji.json`, https://github.com/github/gemoji).
//!    Replaces the runtime `gemoji` Ruby gem (`Emoji.find_by_alias`).
//!    Each `u32` entry in `EMOJI_ENTRIES` is sorted lexicographically by ASCII alias bytes and packs:
//!    - bits `11..32`: byte offset into `EMOJI_BLOB`
//!    - bits `5..11`: byte length of the ASCII alias key (`1..=40`)
//!    - bits `0..5`: UTF-8 byte length of the raw emoji replacement (`1..=28`)
//!
//! 2. **Unicode RGI emoji sequence table (`RGI_EMOJI_BLOB` + `RGI_EMOJI_ENTRIES`)**:
//!    Generated from `emoji_regex` 3.2.3 (`EmojiRegex::RGIEmoji`, Unicode `RGI_Emoji` sequences).
//!    Replaces the runtime `emoji_regex` Ruby gem.
//!    Each `u32` entry in `RGI_EMOJI_ENTRIES` is sorted by `(first_char_utf8_bytes, Reverse(byte_len), full_utf8_bytes)`
//!    so binary search by first UTF-8 character followed by linear scan yields leftmost longest-match semantics, and packs:
//!    - bits `8..32`: byte offset into `RGI_EMOJI_BLOB`
//!    - bits `2..8`: UTF-8 byte length of the full RGI emoji sequence (`3..=35`)
//!    - bits `0..2`: `first_char_utf8_len - 1` (`0..=3`, corresponding to `1..=4` bytes)
//!
//! ## Maintenance & Updating
//! Both datasets are static snapshots of the Unicode Emoji specification and GitHub's `db/emoji.json`.
//! They only need to be regenerated when Forem chooses to adopt a new Unicode Emoji release or add new
//! GitHub shortcode aliases. See `docs/rust_native_extensions.md` ("Maintaining Embedded Static Datasets")
//! for regeneration instructions.

pub(crate) const MAX_EMOJI_ALIAS_LEN: usize = 40;

